from contextlib import contextmanager
from datetime import datetime, timezone
from sqlalchemy import create_engine, text, event
from sqlalchemy.orm import sessionmaker
from config import Config

def normalize_database_url(value):
    if not value:
        raise RuntimeError('DATABASE_URL no esta configurada en el archivo .env')
    from sqlalchemy.engine import make_url
    raw = value.strip()
    if raw.startswith('postgres://'):
        raw = raw.replace('postgres://', 'postgresql://', 1)
    url = make_url(raw)
    if url.drivername in ('postgres', 'postgresql'):
        url = url.set(drivername='postgresql+psycopg')
        query = dict(url.query)
        if url.host and url.host.endswith('.neon.tech'):
            query.setdefault('sslmode', 'require')
        url = url.set(query=query)
    return url

DATABASE_URL = normalize_database_url(Config.DATABASE_URL)
IS_SQLITE = DATABASE_URL.drivername.startswith('sqlite')
engine_options = {
    'pool_pre_ping': True,
    'pool_recycle': 1800,
    'connect_args': {'timeout': 15} if IS_SQLITE else {'connect_timeout': 20, 'keepalives': 1, 'keepalives_idle': 30, 'keepalives_interval': 10, 'keepalives_count': 3}
}
if not IS_SQLITE:
    engine_options.update({'pool_size': Config.DATABASE_POOL_SIZE, 'max_overflow': Config.DATABASE_MAX_OVERFLOW})
engine = create_engine(DATABASE_URL, **engine_options)

SessionLocal = sessionmaker(bind=engine, autoflush=False, expire_on_commit=False)

@event.listens_for(engine, 'connect')
def set_sqlite_foreign_keys(dbapi_connection, connection_record):
    if IS_SQLITE:
        cursor = dbapi_connection.cursor()
        cursor.execute('PRAGMA foreign_keys=ON')
        cursor.close()

@contextmanager
def db_session():
    session = SessionLocal()
    try:
        yield session
        session.commit()
    except Exception:
        session.rollback()
        raise
    finally:
        session.close()

def execute(sql, params=None, session=None):
    statement = text(sql)
    if session is not None:
        return session.execute(statement, params or {})
    with db_session() as current:
        return current.execute(statement, params or {})

def check_connection():
    with engine.connect() as connection:
        return connection.execute(text('SELECT CURRENT_TIMESTAMP')).scalar_one()

def database_health():
    try:
        value = check_connection()
        return {'status': 'ok', 'database': 'postgresql' if not IS_SQLITE else 'sqlite', 'server_time': str(value)}
    except Exception:
        return {'status': 'error', 'database': 'unavailable'}

