        connection.execute(text('CREATE INDEX IF NOT EXISTS ix_equipos_empresa_estado ON equipos(empresa_id, estado)'))
        connection.execute(text('CREATE INDEX IF NOT EXISTS ix_mantenimientos_empresa_fecha ON mantenimientos(empresa_id, fecha)'))
        connection.execute(text('CREATE INDEX IF NOT EXISTS ix_fallas_empresa_estado ON fallas(empresa_id, estado)'))
        connection.execute(text('CREATE INDEX IF NOT EXISTS ix_lecturas_equipo_fecha ON lecturas_horometro(equipo_id, registrado_en)'))
        connection.execute(text('CREATE INDEX IF NOT EXISTS ix_suscripciones_empresa_estado ON suscripciones(empresa_id, estado)'))
        connection.execute(text('CREATE UNIQUE INDEX IF NOT EXISTS uq_usuarios_empresa_usuario ON usuarios(empresa_id, usuario)'))
        connection.execute(text('CREATE UNIQUE INDEX IF NOT EXISTS uq_equipos_empresa_codigo ON equipos(empresa_id, codigo)'))
        connection.execute(text("INSERT INTO planes (codigo,nombre,precio_mensual,max_equipos,indicadores,reportes_exportables,multiples_sedes,soporte_prioritario,activo) VALUES ('free','FREE',0,2,FALSE,FALSE,FALSE,FALSE,TRUE),('basico','Basico',99,10,FALSE,FALSE,FALSE,FALSE,TRUE),('flota','Flota',249,30,TRUE,TRUE,FALSE,FALSE,TRUE),('pro','Pro',449,50,TRUE,TRUE,TRUE,TRUE,TRUE) ON CONFLICT (codigo) DO UPDATE SET nombre=EXCLUDED.nombre,precio_mensual=EXCLUDED.precio_mensual,max_equipos=EXCLUDED.max_equipos,indicadores=EXCLUDED.indicadores,reportes_exportables=EXCLUDED.reportes_exportables,multiples_sedes=EXCLUDED.multiples_sedes,soporte_prioritario=EXCLUDED.soporte_prioritario,activo=TRUE"))
        connection.execute(text("INSERT INTO suscripciones (empresa_id,plan_id,estado,inicio,fin_prueba) SELECT e.id,p.id,'activa',CURRENT_TIMESTAMP,NULL FROM empresas e CROSS JOIN planes p WHERE p.codigo='free' AND NOT EXISTS (SELECT 1 FROM suscripciones s WHERE s.empresa_id=e.id)"))
